const cfg = $node['Laufkonfiguration'].json;
const lines = String($json.stdout || '').split(/\r?\n/).map(s => s.trim()).filter(Boolean);
return lines.map(fragment_path => ({ json: { ...cfg, fragment_path } }));

const item = $node['Nächstes Fragment'].json;
const raw = String($json.stdout || '');
const cut = raw.indexOf('\n---TAXONOMY---\n');
const fragment = cut === -1 ? raw : raw.slice(0, cut);
const taxonomy = cut === -1 ? '' : raw.slice(cut + '\n---TAXONOMY---\n'.length);
const pageLine = (fragment.match(/\*\*Pages:\*\*\s*([^\n]+)/) || [])[1] || '';
const heading = (fragment.match(/^#\s+(.+)$/m) || [])[1] || '';
const book = heading.split(' — ')[0].trim();
const rel = item.fragment_path.split('/Trading/')[1] || item.fragment_path;
const link = `Trading/${rel.replace(/\.md$/, '')}`;
const prompt = [
  'Du prüfst ein Fragment aus einem Fachbuch gegen eine geschlossene Themenliste.',
  'Ein Begriff passt nur, wenn er das Thema eines großen Teils des Fragments ist.',
  'Ein einzelnes vorkommendes Wort reicht nicht.',
  'Passt nichts, gib matches als leeres Array zurück.',
  'Erfinde keine Begriffe. Nur exakte Namen aus der Themenliste.',
  'Antworte nur mit JSON: {"matches":[{"begriff":"exakter Name"}]}',
  '',
  'THEMENLISTE:',
  taxonomy,
  '',
  'FRAGMENT:',
  fragment.slice(0, 12000)
].join('\n');
return [{ json: {
  ...item,
  book,
  pages: pageLine.trim(),
  link,
  ollama_body: {
    model: item.model,
    stream: false,
    format: 'json',
    options: { temperature: 0.1, num_ctx: 8192 },
    prompt
  }
} }];

const base = $node['Bewertungsauftrag bauen'].json;
let parsed = {};
try {
  const body = $json.response ? JSON.parse($json.response) : $json;
  parsed = typeof body === 'string' ? JSON.parse(body) : body;
} catch (e) {
  parsed = { matches: [] };
}
const allowed = new Set();
for (const line of String(base.ollama_body.prompt).split('\n')) {
  const m = line.match(/^\[([ABC])\]\s+(.+)$/);
  if (m) allowed.add(m[2].trim());
}
const matches = [];
const seen = new Set();
for (const row of parsed.matches || []) {
  const name = String(row.begriff || '').trim();
  if (!name || !allowed.has(name) || seen.has(name)) continue;
  seen.add(name);
  matches.push(name);
}
return [{ json: { ...base, matches, ollama_body: undefined } }];

const row = $json;
return row.matches.map(begriff => ({
  json: {
    notes: row.notes,
    append: row.append,
    begriff,
    line: `${row.book}, S. ${row.pages}, [[${row.link}|Fragment]]`
  }
}));
